{"path": "/workspace/target/src/artifact_loader.py", "content": """"Release-population loading and canonical identity join for the deployed candidate.

Release authority:
  * ``source_manifest.json`` declares the active landing files (release population).
    Unlisted landing files (duplicate deliveries) are never part of the population.
  * ``release_registry.jsonl`` is the identity authority. The stable join key is
    ``record_key``; the canonical served identity is the registry ``pmcid`` and the
    registry ``domain``. A landing display ``pmcid`` is not serving identity and may
    be rewritten, projected away, or missing entirely.
"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def _read_jsonl(path: Path) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not path.exists():
        return rows
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        rows.append(json.loads(line))
    return rows


def load_manifest(artifact_root: Path) -> dict[str, Any]:
    path = artifact_root / "source_manifest.json"
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def load_registry(artifact_root: Path, manifest: dict[str, Any]) -> dict[str, dict[str, Any]]:
    name = str(manifest.get("identity_registry") or "release_registry.jsonl")
    registry: dict[str, dict[str, Any]] = {}
    for row in _read_jsonl(artifact_root / name):
        key = row.get("record_key")
        if key is None:
            continue
        registry[str(key)] = row
    return registry


def load_cases(artifact_root: Path) -> list[dict[str, Any]]:
    """Return the release population with canonical identity attached.

    Only manifest-active files contribute. Each landing row is joined to the
    identity registry on ``record_key``; canonical ``pmcid`` and ``source``
    (domain) come from the registry, never from the landing display fields.
    Rows without a registry identity are not release population.
    """
    artifact_root = Path(artifact_root)
    manifest = load_manifest(artifact_root)
    registry = load_registry(artifact_root, manifest)
    join_key = str(manifest.get("identity_key") or "record_key")

    entries = manifest.get("files") or []
    active: list[tuple[str, Path]] = []
    for entry in entries:
        if not entry.get("active", False):
            continue
        rel = str(entry.get("path", ""))
        if not rel:
            continue
        active.append((str(entry.get("domain", "")), artifact_root / rel))

    if not active:  # defensive fallback: manifest unusable
        for path in sorted((artifact_root / "cases").glob("*.jsonl")):
            active.append((path.name.split("_")[0].split("(")[0], path))

    rows: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    for declared_domain, path in active:
        for row in _read_jsonl(path):
            key = row.get(join_key)
            if key is None:
                continue
            key = str(key)
            if key in seen_keys:
                continue
            identity = registry.get(key)
            if identity is None:
                continue
            seen_keys.add(key)
            record = dict(row)
            record["record_key"] = key
            record["pmcid"] = str(identity.get("pmcid", ""))
            record["source"] = str(identity.get("domain") or declared_domain)
            rows.append(record)
    return rows


def load_request(path: Path) -> dict[str, Any]:
    return json.loads(Path(path).read_text(encoding="utf-8"))
"}

{"path": "/workspace/target/src/text_views.py", "content": """"Text normalization and eligible-document assembly for the deployed candidate.

Serving boundary is ``pre_outcome``: only pre-outcome narrative fields are
eligible index text. ``final_diagnosis`` is post-adjudication outcome text and
``domain_hits`` are derived post-hoc counters; neither is eligible. ``journal``
is bibliographic metadata and is not clinical evidence text.
"""
from __future__ import annotations

import re
import unicodedata
from typing import Any

ELIGIBLE_FIELDS = ("title", "case_summary")


def normalize(text: str) -> str:
    text = unicodedata.normalize("NFKC", str(text)).lower()
    return re.sub(r"\s+", " ", text).strip()


def document_text(row: dict[str, Any]) -> str:
    return normalize(" ".join(str(row.get(field, "")) for field in ELIGIBLE_FIELDS))


def query_text(facet_value: Any) -> str:
    return normalize(str(facet_value))
"}

